private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int octet = 0;
    while (i < bb.limit()) {
        octet = bb.get(i);
        i++;
        if ((octet & 0x80) == 0) {
            sb.append((char) octet);
        } else if ((octet & 0xE0) == 0xC0) {
            octet = (octet & 0x1F) << 6;
            octet |= (bb.get(i) & 0x3F);
            sb.append((char) octet);
            i++;
        } else if ((octet & 0xF0) == 0xE0) {
            octet = (octet & 0x0F) << 12;
            octet |= (bb.get(i) & 0x3F) << 6;
            octet |= (bb.get(i + 1) & 0x3F);
            sb.append((char) octet);
            i += 2;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 encoding encountered at index " + i);
        }
    }
    return i;
}

