public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("Illegal Capacity: " + desiredCapacity);
    }

    int n = desiredCapacity;
    boolean isPrime = false;
    while (!isPrime) {
        if (n % 2 == 0) {
            n++;
        } else if (n % 3 == 0) {
            n += 2;
        } else if (n % 5 == 0) {
            n += 4;
        } else if (n % 7 == 0) {
            n += 6;
        } else if (n % 11 == 0) {
            n += 10;
        } else {
            isPrime = true;
        }
    }

    return n;
}

