public long readRawVarint64() throws IOException {
    long result = 0;
    int offset = 0;
    byte b;
    do {
        if (offset < 64) {
            b = readByte();
            result |= (long)(b & 0x7F) << offset;
        }
        else {
            throw new IOException("Invalid Varint encountered.");
        }
        offset += 7;
    } while ((b & 0x80) != 0);
    return result;
}

